package com.example.stokbarang;
import android.app.*;
import android.os.*;
import android.content.*;
import android.database.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    DatabaseHelper db; LinearLayout page,content; String csv=""; final int SAVE_CSV=9;
    int blue=0xff1565c0;
    public void onCreate(Bundle b){super.onCreate(b);db=new DatabaseHelper(this);home();}
    TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff172033);t.setPadding(12,10,12,10);return t;}
    Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
    EditText edit(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);return e;}
    void base(String title){page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(0xfff4f7fb);TextView h=label(title,21);h.setTextColor(-1);h.setBackgroundColor(blue);page.addView(h);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setPadding(12,8,12,20);content.setOrientation(1);sc.addView(content);page.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(page);}
    void home(){base("Stok Barang");Cursor s=db.summary();int n=0,l=0;if(s.moveToFirst()){n=s.getInt(0);l=s.getInt(1);}s.close();content.addView(label("Total material: "+n+"     Stok menipis: "+l,17));content.addView(btn("📦 Master Data Material",this::materials));content.addView(btn("⬇ Transaksi Stok Masuk",()->transaction("MASUK")));content.addView(btn("⬆ Transaksi Stok Keluar",()->transaction("KELUAR")));content.addView(btn("📋 Riwayat Transaksi",this::history));content.addView(btn("📊 Laporan & Ekspor CSV",this::report));content.addView(label("Offline • SQLite • 200 data awal",13));}
    void materials(){base("Master Data");EditText search=edit("Cari material / kode","");content.addView(search);content.addView(btn("+ Tambah Material",()->materialForm(null)));LinearLayout list=new LinearLayout(this);list.setOrientation(1);content.addView(list);Runnable load=()->{list.removeAllViews();Cursor c=db.materials(search.getText().toString());while(c.moveToNext()){long id=c.getLong(0);String code=c.getString(1),name=c.getString(2),cat=c.getString(3),unit=c.getString(4);double stock=c.getDouble(5),min=c.getDouble(6);list.addView(label(name+"\n"+code+" • "+cat+"\nStok "+stock+" "+unit+" | Min "+min,15));list.addView(btn("Edit",()->materialForm(new String[]{""+id,code,name,cat,unit,""+min})));list.addView(btn("Nonaktifkan",()->new AlertDialog.Builder(this).setMessage("Nonaktifkan "+name+"?").setNegativeButton("Batal",null).setPositiveButton("Ya",(a,b)->{db.deactivate(id);materials();}).show()));}c.close();};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){load.run();}public void afterTextChanged(android.text.Editable e){}});load.run();content.addView(btn("Kembali",this::home));}
    void materialForm(String[] old){LinearLayout f=new LinearLayout(this);f.setPadding(15,0,15,0);f.setOrientation(1);EditText code=edit("Kode",old==null?"":old[1]),name=edit("Nama material",old==null?"":old[2]),cat=edit("Kategori",old==null?"Umum":old[3]),unit=edit("Satuan",old==null?"pcs":old[4]),min=edit("Stok minimum",old==null?"0":old[5]);f.addView(code);f.addView(name);f.addView(cat);f.addView(unit);f.addView(min);new AlertDialog.Builder(this).setTitle(old==null?"Tambah Material":"Edit Material").setView(f).setNegativeButton("Batal",null).setPositiveButton("Simpan",(d,w)->{try{if(code.length()==0||name.length()==0)throw new Exception();db.save(old==null?0:Long.parseLong(old[0]),code.getText().toString(),name.getText().toString(),cat.getText().toString(),unit.getText().toString(),Double.parseDouble(min.getText().toString()));materials();}catch(Exception e){msg("Data tidak valid atau kode sudah dipakai.");}}).show();}
    void transaction(String type){base(type.equals("MASUK")?"Stok Masuk":"Stok Keluar");Cursor c=db.materials("");ArrayList<Long> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();while(c.moveToNext()){ids.add(c.getLong(0));names.add(c.getString(2)+" ("+c.getString(4)+") stok "+c.getDouble(5));}c.close();Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));EditText qty=edit("Jumlah",""),date=edit("Tanggal YYYY-MM-DD",new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())),note=edit("Keterangan","");content.addView(label("Material",15));content.addView(sp);content.addView(qty);content.addView(date);content.addView(note);content.addView(btn("Simpan",()->{try{int p=sp.getSelectedItemPosition();if(p<0)throw new Exception();if(db.transact(ids.get(p),type,Double.parseDouble(qty.getText().toString()),date.getText().toString(),note.getText().toString())){msg("Transaksi tersimpan");home();}else msg("Gagal: stok keluar melebihi stok tersedia.");}catch(Exception e){msg("Lengkapi data transaksi.");}}));content.addView(btn("Kembali",this::home));}
    void history(){base("Riwayat Transaksi");Cursor c=db.history();while(c.moveToNext())content.addView(label(c.getString(0)+" • "+c.getString(2)+"\n"+c.getString(1)+"\n"+c.getDouble(3)+" "+c.getString(4)+" | "+c.getDouble(5)+" → "+c.getDouble(6)+"\n"+c.getString(7),14));c.close();content.addView(btn("Kembali",this::home));}
    String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
    void report(){base("Laporan Stok");Cursor c=db.materials("");StringBuilder b=new StringBuilder("Kode,Nama,Kategori,Satuan,Stok,Minimum\n");while(c.moveToNext()){String code=c.getString(1),name=c.getString(2),cat=c.getString(3),unit=c.getString(4);double stock=c.getDouble(5),min=c.getDouble(6);content.addView(label(name+" | "+stock+" "+unit+(stock<=min?" • MENIPIS":""),14));b.append(q(code)+","+q(name)+","+q(cat)+","+q(unit)+","+stock+","+min+"\n");}c.close();content.addView(btn("Ekspor Stok ke CSV",()->saveCsv(b.toString(),"laporan_stok.csv")));content.addView(btn("Ekspor Riwayat ke CSV",()->{Cursor h=db.history();StringBuilder x=new StringBuilder("Tanggal,Material,Jenis,Jumlah,Satuan,Sebelum,Sesudah,Keterangan\n");while(h.moveToNext()){for(int i=0;i<8;i++){if(i>0)x.append(",");x.append(q(h.getString(i)));}x.append("\n");}h.close();saveCsv(x.toString(),"riwayat_transaksi.csv");}));content.addView(btn("Kembali",this::home));}
    void saveCsv(String data,String filename){csv=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,SAVE_CSV);}
    protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==SAVE_CSV&&result==RESULT_OK&&data!=null)try{OutputStream o=getContentResolver().openOutputStream(data.getData());OutputStreamWriter w=new OutputStreamWriter(o,"UTF-8");w.write('\uFEFF');w.write(csv);w.close();msg("CSV tersimpan");}catch(Exception e){msg("Gagal menyimpan CSV");}}
    void msg(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
